for(let i=0;i<6;i++){const f=document.createElement('div');f.className='floor';f.dataset.level=i;let inside='';if(i===0)inside='<div class="park">'+ '<i></i>'.repeat(6)+'</div>';else if(i===1)inside='<div class="smallrooms">'+'<i></i>'.repeat(4)+'</div><div class="pool"></div><div class="amenity"></div>';else if(i===5)inside='<div class="cafe">'+'<i></i>'.repeat(8)+'</div>';else inside='<div class="rooms">'+'<i class="cell"></i>'.repeat(6)+'<div class="corridor"></div>'+'<i class="cell"></i>'.repeat(6)+'</div>';f.innerHTML=inside+'<span class="floor-tag">'+(i?'L'+i:'G')+'</span>';world.append(f)}
