for(const id of ['floor-nav','plan-nav']){floors.forEach((f,i)=>{let b=document.createElement('button');b.textContent=i?'L'+i:'G';b.setAttribute('aria-label',(i?'Lantai '+i:'Lantai dasar')+' '+f.title);b.onclick=()=>{select(i);if(id==='floor-nav'){manual=true;setSpread(1)}};$('#'+id).append(b)})}
function select(i){selected=i;$('#level-id').textContent=i?'L'+i:'GROUND';$('#level-name').textContent=floors[i].title;$('#level-desc').textContent=floors[i].desc;$('#level-meta').textContent=floors[i].meta;$('#plan-title').textContent=floors[i].plan;$('#plan-copy').textContent=floors[i].copy;plates.forEach((p,j)=>p.classList.toggle('selected',i===j));for(const id of ['floor-nav','plan-nav'])[...$('#'+id).children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',String(i===j))});drawPlan(i)}
function setSpread(p){spread=p;plates.forEach((el,i)=>{el.style.transform=`translateZ(${i*(23+p*49)+9}px)`});$('#explode').value=Math.round(p*100);$('#amount').textContent=Math.round(p*100)+'%'}
$('#explode').oninput=e=>{manual=true;setSpread(+e.target.value/100)};$('#auto').onclick=()=>{manual=false;update()};
