let ticking=false;function update(){ticking=false;let r=$('#layers').getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/(r.height-innerHeight)));if(!manual){setSpread(reduced.matches?1:p);let i=Math.min(5,Math.floor(p*6));if(i!==selected)select(i)}if(!reduced.matches){$('.hero>img').style.transform=`translateY(${Math.min(scrollY*.22,innerHeight*.4)}px)`;$('.hero-copy').style.transform=`translateY(${Math.min(scrollY*.10,100)}px)`}}
addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(update);ticking=true}},{passive:true});addEventListener('resize',update);reduced.addEventListener('change',update);document.documentElement.classList.add('js');new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.15}).observe($('.intro h2'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.1});document.querySelectorAll('.reveal').forEach(e=>io.observe(e));select(0);update();
// Original slow pentatonic instrumental, synthesized locally; no external music or tracking.
let ctx,master,timer,on=false,noteIndex=0;const melody=[0,7,12,16,14,12,7,4,0,7,11,14,12,7,4,2];
function note(freq,t,dur,volume){for(let h=1;h<=3;h++){let o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq*h;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume/(h*h),t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(master);o.start(t);o.stop(t+dur+.1)}}
function phrase(){if(!on)return;const t=ctx.currentTime;note(220*Math.pow(2,melody[noteIndex%melody.length]/12),t,3.5,.13);if(noteIndex%4===0){note(110,t,5,.08);note(164.81,t+.07,5,.05)}noteIndex++}
async function toggleMusic(){try{if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.gain.value=.5;master.connect(ctx.destination)}if(on){on=false;clearInterval(timer);await ctx.suspend()}else{await ctx.resume();on=true;phrase();timer=setInterval(phrase,900)}$('#music').setAttribute('aria-pressed',String(on));$('#music span').textContent=on?'Music on':'Music off'}catch(e){$('#music span').textContent='Tap to retry';on=false;clearInterval(timer)}}$('#music').onclick=toggleMusic;document.addEventListener('visibilitychange',()=>{if(document.hidden&&on)toggleMusic()});
